  "d.1ysusgc": "Movt máksojuvvon alusat bissot rehálažžan spealli-vuostá-spealli dilis, lea ain hábmejuvvomin.",
  "d.21ryis": "ATTACK-ráhkkanusat molsot ovtta ulbmila ja lagamus ulbmila gaskkas.",
  "d.2pbr86": "Gaskkalaš",
  "d.2r8k8j": "DÁLKI",
  "d.2sqinp": "Golbma alusa mohtorsuovvaiguin sevdnjes Glasgow badjel, ja bilohta alus ovdalis.",
  "d.2vomdh": "Automáhtalaš sullásašvuođaskánnen speallu koda ektui GPL-prototiipa gáldokoda lei čađahuvvon {date0}. Áššedovdiid geahčadeapmi gávdnon sajiin lea fámus. Juohke mii gávdnojuvvo kopierejuvvon dahje heivehuvvon, čállojuvvo ođđasit.",
  "d.32ogvm": "Mohtorsuovvat stuorrudaga mielde, 240 m stuorra ANVIL mas lea čađačuovgi hangára ja uksat, NEEDLE-alusat vuolget goabbáge beallái, okta- dahje lagamus-ulbmila ATTACK-molsun, ja AI-ANVIL-alusat mat bidjet iežaset sihpuid johtui.",
  "d.3b0pca": "GUORAHALLANALUS",
  "d.3bxw4p": "Vuosttaš almmolaš ruhtačoaggin.",
  "d.3ednu": "Ollis ođđasit huksen AI-BuB-mohtoris Unreal Engine 5:ii",
  "d.3m3q6c": "Beaivvášliekkas, ja čuvggaheamit juohke moadde minuhta.",
  "d.3wpyge": "Guhttanuppelohkái kilomehtera gávpot Clyde guovlluin vuolit hárve almmi vuolde. Duohta gravitaššuvdna, duohta áibmu, hálbbit ja kránat: doala johtolaga bajil ja njunni eret johkas.",
  "d.4b5t91": "PERIHELION, 4 SOLAR RADII, sektorgovva speallu fállolisttus. Speallogovva, veršuvdna 0.6.1",
  "d.4p55jj": "alusluohkát",
  "d.4pqks5": "Speallu koda sirdojuvvo BuB-ii, ođđa mohtorii mii lea čállojuvvon Claude Code geavahemiin. Speallomodulat bohtet prototiippas ja nammaiduvvojuvvojit maŋŋelaš.",
  "d.4wz1ss": "LOADOUT-čájáhus juohke stoahkaga ovdal (oktaspealli ja multispeallu-lobbi) mas leat alusgorut- ja gáhttejumidásit, gáhttejumi ivdni, gierdomearkaráiddut ja ANVIL-arastu alusat.",
  "d.5h9ajx": "LASERAT",
  "d.5zdnfb": "Vakuuma: ii vuostebáhkka.",
  "d.61r5q7": "HANGÁRARASTU 10 NEEDLE-ALUSIIN",
  "d.6mw8fz": "Laser- ja bohccitorráid bargolávvit mat álget AUTO:s.",
  "d.6vf32z": "Veršuvdna 0 (demo) jikŋon: 8 alusluohká, laserat ja salvvafámut, THETA-7 asteroidefáddá.",
  "d.6wbq2y": "Beaivváža skearru, jaskes govva kárttaguorahalliide.",
  "d.709qra": "Doala dievasmuvvat, luoita bossut. Luoitin 50 % dahje eambbo dievasmuvvamis bossá; dan vuolábealde dat gaskkalduvvo.",
  "d.7a27ds": "Gierdomearkasajit, guhtta raketa salvvat čuovvugameraiguin, duppal lasihus, ANVIL ripple-laserat, ANVIL-arastu mii vuolggaha 10 searválaš NEEDLE-alusa, ja gamera cuigimis sláider.",
  "d.7xvt5u": "Buot ovdánahttojuvvo AI:in BuB-mohtoris, Claude Code geavahemiin.",
  "d.87vl1g": "Báikkálaš fierpmádatmultispeallu (gávdnat speallat seamma Wi-Fi:s, doallat dahje searvat lobbái, vuolgit ovttas; ovttasbargoaallogat ja juohkehaš iežas ovddas) ja golbma ođđa kárta: LUNA, EARTH ORBIT ja SOL.",
  "d.899luq": "THRESHER nugo čájehuvvo speallu hangárlisttus, veršuvnna 0.6.1 alusgorut, golmma njealjádasa oaidnu čáhppat duogážis.",
  "d.90i5d3": "Dálki.",
  "d.99x268": "PATHFINDER nugo čájehuvvo speallu hangárlisttus, veršuvnna 0.6.1 alusgorut, golmma njealjádasa oaidnu čáhppat duogážis.",
  "d.9kqiam": "Stoahkka álgá idjabealde, ja orbitála beaivválgin boahtá golmma minuhta maŋŋá.",
  "d.9mbw4g": "TERMINATORA",
  "d.9o257g": "Veršuvdna 0.2.1 jikŋon: minigunat, ja gieđalaš ja automáhtalaš áimmuheapmi laseraide, minigunaide ja raketaide.",
  "d.9rtpka": "MULE nugo čájehuvvo speallu hangárlisttus, veršuvnna 0.6.1 alusgorut, golmma njealjádasa oaidnu čáhppat duogážis.",
